def test_get_truncate_datetime(self):
    result = get_truncate_datetime('hour')
    assert 'hour' == result
    with pytest.raises(ValueError):
        get_truncate_datetime('blah')

def get_truncate_datetime(truncate_datetime):
    valid_values = {'second', 'minute', 'hour', 'day'}
    if truncate_datetime not in valid_values:
        raise ValueError(f"truncate_datetime must be one of {valid_values}, got {truncate_datetime!r}")
    return truncate_datetime
